#!/usr/bin/env bash
# gaps-fixed.sh -- regenerate docs/GAPS_FIXED.md from docs/LEDGER.tsv and the audit notes in docs/tracker/.
set -euo pipefail
cd "$(dirname "$0")/.."
python3 - <<'PY'
import csv, glob, os, re
rows = list(csv.DictReader(open('docs/LEDGER.tsv'), delimiter='\t'))
out = ['# Gaps fixed', '',
       'Generated by `scripts/gaps-fixed.sh` from `docs/LEDGER.tsv` and `docs/tracker/*.md`. Do not edit by hand.', '']
for kind, title in (('pr', 'Upstream pull requests'), ('issue', 'Upstream issues')):
    sel = [r for r in rows if r['kind'] == kind]
    done = [r for r in sel if r['state'] == 'DONE']
    skipped = [r for r in sel if r['state'] == 'SKIPPED']
    out += ['## %s' % title, '', '%d total: %d fixed on master, %d skipped (already present or obsolete), %d open.' %
            (len(sel), len(done), len(skipped), len(sel) - len(done) - len(skipped)), '',
            '| # | Title | State | Commit |', '|---|---|---|---|']
    for r in sorted(sel, key=lambda r: int(r['number'])):
        t = r['title'].replace('|', '/')[:90]
        out.append('| [#%s](%s) | %s | %s | %s |' % (r['number'], r['url'], t, r['state'], ('`%s`' % r['commit']) if r['commit'] else '-'))
    out.append('')
fixed, still = [], 0
for f in sorted(glob.glob('docs/tracker/*.md')):
    for line in open(f, encoding='utf-8', errors='replace'):
        if 'FIXED' in line and '|' in line:
            fixed.append((os.path.basename(f)[:-3], line.strip()))
        if 'STILL OPEN' in line: still += 1
out += ['## Parity audit gaps', '',
        'Audit notes under `docs/tracker/` record each vanilla gap. Rows marked FIXED: %d. Lines marked STILL OPEN: %d (see each note for the reason).' % (len(fixed), still), '']
for slug, line in fixed:
    out.append('- `%s`: %s' % (slug, re.sub(r'\s+', ' ', line)[:200]))
open('docs/GAPS_FIXED.md', 'w').write('\n'.join(out) + '\n')
PY
